const express = require('express');
const { EventStoreDBClient, START } = require('@eventstore/db-client');
const { verifySessionToken } = require('../auth');
const Cart = require('../models/Cart');

const router = express.Router();
const eventStore = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URL);

router.get('/api/queries/carts/:cartId/audit', verifySessionToken, async (req, res) => {
  const { cartId } = req.params;

  const cart = await Cart.findOne({ id: cartId, userId: req.user.id });
  if (!cart) {
    return res.status(403).json({ error: 'Access denied to cart audit trail' });
  }

  const cartEvents = [];
  const stream = eventStore.readStream(`cart-${cartId}`, { fromRevision: START });
  for await (const { event } of stream) {
    cartEvents.push({ type: event.type, data: event.data });
  }

  res.json({ cartId, auditTrail: cartEvents });
});
